import Foundation
import CPdfium

/// A search hit: a character range on the page, with the quads covering it.
public struct PdfTextMatch: Equatable, Sendable {
    public let range: Range<Int>
    public let rects: [PdfRect]
}

/// Text extraction and search for one page.
public struct PdfTextPage: Sendable {
    public let document: PdfDocument
    public let pageIndex: Int

    /// Number of characters, including whitespace generated by layout.
    public var characterCount: Int {
        get async throws { try await document.textCharacterCount(pageIndex) }
    }

    /// The page's full text in reading order.
    public func string() async throws -> String {
        try await document.textString(pageIndex)
    }

    /// The bounding box of one character, in page space.
    public func boundingBox(ofCharacterAt index: Int) async throws -> PdfRect {
        try await document.textCharBox(pageIndex, index)
    }

    public func search(_ query: String, options: PdfSearchOptions = .none) async throws -> [PdfTextMatch] {
        try await document.textSearch(pageIndex, query, options)
    }
}

extension PdfDocument {
    /// Loads a text page, runs `body`, and always closes it.
    private func withTextPage<T>(_ index: Int, _ body: (FPDF_TEXTPAGE) throws -> T) throws -> T {
        let page = try loadedPage(index)
        guard let textPage = FPDFText_LoadPage(page) else {
            throw PdfError.corrupt(detail: "text layer for page \(index) failed to load")
        }
        defer { FPDFText_ClosePage(textPage) }
        return try body(textPage)
    }

    func textCharacterCount(_ index: Int) throws -> Int {
        try withTextPage(index) { Int(max(0, FPDFText_CountChars($0))) }
    }

    func textString(_ index: Int) throws -> String {
        try withTextPage(index) { textPage in
            let count = FPDFText_CountChars(textPage)
            guard count > 0 else { return "" }
            // +1 for the terminator PDFium appends.
            var buffer = [UInt16](repeating: 0, count: Int(count) + 1)
            let written = FPDFText_GetText(textPage, 0, count, &buffer)
            guard written > 0 else { return "" }
            return String(decoding: buffer[0..<Int(written - 1)], as: UTF16.self)
        }
    }

    func textCharBox(_ index: Int, _ charIndex: Int) throws -> PdfRect {
        try withTextPage(index) { textPage in
            let count = Int(FPDFText_CountChars(textPage))
            guard charIndex >= 0 && charIndex < count else {
                throw PdfError.pageOutOfRange(charIndex, count: count)
            }
            var left = 0.0, right = 0.0, bottom = 0.0, top = 0.0
            FPDFText_GetCharBox(textPage, Int32(charIndex), &left, &right, &bottom, &top)
            return PdfRect(left: left, bottom: bottom, right: right, top: top)
        }
    }

    func textSearch(_ index: Int, _ query: String, _ options: PdfSearchOptions) throws -> [PdfTextMatch] {
        guard !query.isEmpty else { return [] }
        return try withTextPage(index) { textPage in
            var flags: UInt = 0
            if options.contains(.caseSensitive) { flags |= UInt(FPDF_MATCHCASE) }
            if options.contains(.wholeWord) { flags |= UInt(FPDF_MATCHWHOLEWORD) }

            var term = Array(query.utf16) + [0]
            guard let search = FPDFText_FindStart(textPage, &term, flags, 0) else { return [] }
            defer { FPDFText_FindClose(search) }

            var matches: [PdfTextMatch] = []
            while FPDFText_FindNext(search) != 0 {
                let start = Int(FPDFText_GetSchResultIndex(search))
                let length = Int(FPDFText_GetSchCount(search))
                guard length > 0 else { continue }

                let rectCount = Int(FPDFText_CountRects(textPage, Int32(start), Int32(length)))
                var rects: [PdfRect] = []
                for r in 0..<max(0, rectCount) {
                    var left = 0.0, top = 0.0, right = 0.0, bottom = 0.0
                    FPDFText_GetRect(textPage, Int32(r), &left, &top, &right, &bottom)
                    rects.append(PdfRect(left: left, bottom: bottom, right: right, top: top))
                }
                matches.append(PdfTextMatch(range: start..<(start + length), rects: rects))
            }
            return matches
        }
    }
}
